package com.renthub.favorite; import com.renthub.auth.AuthService; import com.renthub.user.User; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/api/favorites") @CrossOrigin(origins="http://localhost:5173") public class FavoriteController{private final FavoriteRepository repo;private final AuthService auth;public FavoriteController(FavoriteRepository r,AuthService a){repo=r;auth=a;} @GetMapping public List<Favorite> all(@RequestHeader(value="Authorization",required=false)String h){return repo.findByUserIdOrderByIdDesc(auth.require(h).getId());} @PostMapping public Favorite add(@RequestHeader(value="Authorization",required=false)String h,@RequestBody Map<String,Object>b){User u=auth.require(h);String t=String.valueOf(b.get("assetType")).toUpperCase();Long id=Long.valueOf(String.valueOf(b.get("assetId")));return repo.findByUserIdAndAssetTypeAndAssetId(u.getId(),t,id).orElseGet(()->{Favorite f=new Favorite();f.setUserId(u.getId());f.setAssetType(t);f.setAssetId(id);return repo.save(f);});} @DeleteMapping("/{type}/{assetId}") public void remove(@RequestHeader(value="Authorization",required=false)String h,@PathVariable String type,@PathVariable Long assetId){User u=auth.require(h);repo.findByUserIdAndAssetTypeAndAssetId(u.getId(),type.toUpperCase(),assetId).ifPresent(repo::delete);}}
